INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der wirtschaftlichen Machbarkeit entscheidend?', 2, '[{"text": "Kosten-Nutzen-Verhältnis", "correct": true, "because": "Bestimmt Rentabilität"}, {"text": "Design der Produkte", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die wirtschaftliche Machbarkeit immer von der Marktnachfrage abhängig?', 1, '[{"text": "Nein", "correct": true, "because": "Interne Kostenersparnis möglich"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich Nachfrage"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind für die wirtschaftliche Machbarkeit wichtig?', 5, '[{"text": "Investitionskosten", "correct": true, "because": "Beeinflussen Anfangskapital"}, {"text": "ROI (Return on Investment)", "correct": true, "because": "Misst Rentabilität"}, {"text": "Farbe der Produkte", "correct": false, "because": "Kein Einfluss"}, {"text": "Betriebskosten", "correct": true, "because": "Langfristige Ausgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über wirtschaftliche Machbarkeit richtig? a) Sie prüft die Rentabilität eines Projekts. b) Sie ist unabhängig von technischen Aspekten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Technik beeinflusst Kosten"}, {"text": "Beides stimmt", "correct": false, "because": "Technik ist relevant"}, {"text": "Nur b) stimmt", "correct": false, "because": "Rentabilität ist Kern"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der wirtschaftlichen Machbarkeit ignorieren?', 2, '[{"text": "Kostenanalyse", "correct": false, "because": "Wichtig für Rentabilität"}, {"text": "Produktdesign", "correct": true, "because": "Technisch, nicht wirtschaftlich"}, {"text": "Amortisationszeit", "correct": false, "because": "Entscheidend für Rückfluss"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der wirtschaftlichen Machbarkeit entscheidend?', 2, '[{"text": "Kosten-Nutzen-Verhältnis", "correct": true, "because": "Bestimmt Rentabilität"}, {"text": "Farbe der Berichte", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die wirtschaftliche Machbarkeit immer von staatlichen Förderungen abhängig?', 1, '[{"text": "Nein", "correct": true, "because": "Eigene Mittel können reichen"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind für die wirtschaftliche Machbarkeit wichtig?', 5, '[{"text": "Investitionskosten", "correct": true, "because": "Beeinflussen Startkapital"}, {"text": "Erwartete Einnahmen", "correct": true, "because": "Bestimmen Gewinn"}, {"text": "Design der Präsentation", "correct": false, "because": "Nur Darstellung"}, {"text": "Rückflussrate", "correct": true, "because": "Zeigt Rentabilität"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über wirtschaftliche Machbarkeit richtig? a) Sie prüft die Rentabilität eines Projekts. b) Sie berücksichtigt nur technische Aspekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rentabilität zentral, Technik separat"}, {"text": "Beides stimmt", "correct": false, "because": "Technik nicht Teil"}, {"text": "Nur b) stimmt", "correct": false, "because": "Wirtschaft im Fokus"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der wirtschaftlichen Machbarkeit ignorieren?', 2, '[{"text": "Kostenplanung", "correct": false, "because": "Wichtig für Budget"}, {"text": "Farbe der Tabellen", "correct": true, "because": "Kein Einfluss auf Analyse"}, {"text": "Amortisationszeit", "correct": false, "because": "Entscheidend für Rentabilität"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
