('00000000-0000-0000-0000-000000000000', 'Ist die wirtschaftliche Machbarkeit immer von der technischen Machbarkeit abhängig?', 1, '[{"text": "Nein", "correct": true, "because": "Kosten unabhängig prüfbar"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig gekoppelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind für die wirtschaftliche Machbarkeit wichtig?', 5, '[{"text": "Investitionskosten", "correct": true, "because": "Beeinflussen Anfangsausgaben"}, {"text": "Renditeerwartung", "correct": true, "because": "Bestimmt Gewinn"}, {"text": "Schriftart der Analyse", "correct": false, "because": "Kein Einfluss"}, {"text": "Laufende Kosten", "correct": true, "because": "Langfristige Ausgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über wirtschaftliche Machbarkeit richtig? a) Sie prüft die Rentabilität eines Projekts. b) Sie ignoriert technische Aspekte vollständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rentabilität zentral, Technik relevant"}, {"text": "Beides stimmt", "correct": false, "because": "Technik wird berücksichtigt"}, {"text": "Nur b) stimmt", "correct": false, "because": "Rentabilität ist Kern"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der wirtschaftlichen Machbarkeit eines Projekts ignorieren?', 2, '[{"text": "ROI (Return on Investment)", "correct": false, "because": "Wichtig für Gewinn"}, {"text": "Farbe der Analyseunterlagen", "correct": true, "because": "Kein Einfluss auf Wirtschaftlichkeit"}, {"text": "Amortisationszeit", "correct": false, "because": "Entscheidend für Planung"}]');
